(function(){
  function ensure(){if($('#guidedOverlays'))return;const section=document.createElement('section');section.className='card wide';section.innerHTML='<h2>Affichage dans la vidéo</h2><div id="guidedOverlays" class="list"></div><button id="guidedAddOverlay" type="button">Créer un overlay autonome</button>';$('#phenomena').closest('.card').after(section)}
  const oldLists=renderLists;renderLists=function(){oldLists();ensure();const box=$('#guidedOverlays');box.innerHTML=(state.activity.overlays||[]).map(x=>`<div class="item" data-guided-overlay-id="${esc(x.id)}"><span>${esc(x.title||'Overlay sans titre')}</span><span class="muted">${mm(x.startMs)} — ${mm(x.endMs)}</span></div>`).join('')||'<p class="muted">Aucun overlay.</p>';box.querySelectorAll('[data-guided-overlay-id]').forEach(n=>n.onclick=()=>select((state.activity.overlays||[]).find(x=>x.id===n.dataset.guidedOverlayId),'overlay'))};
  const oldFind=find;find=function(type,id){if(type==='overlay')return(state.activity.overlays||[]).find(x=>x.id===id);return oldFind(type,id)};
  const oldSelect=select;select=function(item,type){if(type==='overlay'){if(!item)return;selected={item,type};video.currentTime=item.startMs/1000;$('#summary').textContent=`Affichage dans la vidéo · ${mm(item.startMs)} — ${mm(item.endMs)}`;renderEditor();return}oldSelect(item,type)};
  const oldEditor=renderEditor;renderEditor=function(){if(selected?.type==='overlay'){const x=selected.item,a=state.activity;$('#editor').innerHTML=`<div class="form"><strong>Affichage dans la vidéo</strong><label>Annotation liée (optionnelle)<select id="goAnnotation"><option value="">Aucune</option>${(a.teacherAnnotations||[]).map(i=>`<option value="${esc(i.id)}" ${i.id===x.annotationId?'selected':''}>${esc(i.note||i.id)}</option>`).join('')}</select></label><label>Début (ms)<input id="goStart" type="number" min="0" value="${x.startMs}"></label><label>Fin (ms)<input id="goEnd" type="number" min="0" value="${x.endMs}"></label><label class="fullrow">Titre<textarea id="goTitle">${esc(x.title||'')}</textarea></label><label class="fullrow">Texte<textarea id="goText">${esc(x.text||'')}</textarea></label><label class="fullrow">Couches<select id="goLayers" multiple size="4">${(a.layers||[]).map(l=>`<option value="${esc(l.id)}" ${(x.layerIds||[]).includes(l.id)?'selected':''}>${esc(l.label)}</option>`).join('')}</select></label></div><button id="goApply" type="button">Appliquer</button><button id="goRemove" class="secondary" type="button">Supprimer l’overlay</button>`;$('#goApply').onclick=()=>{const s=Number($('#goStart').value),e=Number($('#goEnd').value),max=Number(a.video.durationMs);if(!Number.isInteger(s)||!Number.isInteger(e)||s<0||e<=s||(max>0&&e>max)){$('#status').textContent='Temps d’overlay invalides.';return}x.annotationId=$('#goAnnotation').value||undefined;x.startMs=s;x.endMs=e;x.title=$('#goTitle').value;x.text=$('#goText').value;x.layerIds=[...$('#goLayers').selectedOptions].map(o=>o.value);$('#status').textContent='Overlay modifié. Enregistrez pour confirmer.';render()};$('#goRemove').onclick=()=>{state.activity.overlays=state.activity.overlays.filter(i=>i.id!==x.id);selected=null;markGuidedDirty('Overlay supprimé. Enregistrez pour confirmer.');render()};return}if(selected?.type==='annotation'){const x=selected.item;$('#editor').innerHTML=`<div class="form"><strong>Annotation pédagogique</strong><label>Segment<select id="gaSegment">${(state.activity.segments||[]).map(s=>`<option value="${esc(s.id)}" ${s.id===x.segmentId?'selected':''}>${esc(s.text||s.id)}</option>`).join('')}</select></label><label class="fullrow">Texte<textarea id="gaNote">${esc(x.note||'')}</textarea></label><label class="fullrow">Question pédagogique<textarea id="gaQuestion">${esc(x.pedagogicalQuestion||'')}</textarea></label></div><button id="gaApply" type="button">Appliquer</button><button id="gaRemove" class="secondary" type="button">Supprimer</button>`;$('#gaApply').onclick=()=>{x.segmentId=$('#gaSegment').value;x.note=$('#gaNote').value;x.pedagogicalQuestion=$('#gaQuestion').value;delete x.overlay;$('#status').textContent='Annotation modifiée. Enregistrez pour confirmer.';render()};$('#gaRemove').onclick=()=>{state.activity.teacherAnnotations=state.activity.teacherAnnotations.filter(i=>i.id!==x.id);selected=null;markGuidedDirty('Annotation supprimée. Enregistrez pour confirmer.');render()};return}oldEditor()};
  document.addEventListener('click',event=>{if(event.target.id!=='guidedAddOverlay')return;const s=Math.round(video.currentTime*1000),x={id:`overlay-guided-${Date.now()}`,startMs:s,endMs:s+1000,title:'',text:'',layerIds:[]};state.activity.overlays.push(x);select(x,'overlay');$('#status').textContent='Overlay ajouté. Enregistrez pour confirmer.'});
  $('#save').onclick=async()=>{if(state.relationIssue){$('#status').textContent=state.relationIssue;return}syncDerivedPhenomenonIds();const p=Proto05GuidedAuthoring.buildAuthoringPayload(state.activity),r=await fetch('/api/proto05/activities/'+encodeURIComponent(id)+'/authoring',{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify(p)}),j=await r.json();$('#status').textContent=r.ok?'Modifications enregistrées.':(j.error||'Enregistrement impossible.');if(r.ok){state.activity=j.activity;render()}};
  if(state.activity)render();
})();
